INSERT INTO evaluations(id,system_id,system_name,evaluator_id,evaluator_name,user_role,before_answers,after_answers,before_average,after_average,comparable_count,feedback,submitted_at) SELECT s.id,s.system_id,sys.name,s.user_id,u.display_name,s.user_role,s.before_answers,s.after_answers,s.before_average,s.after_average,CASE WHEN json_array_length(s.before_answers)>0 THEN 10 ELSE 0 END,s.feedback,s.submitted_at FROM mock_eval_seed s JOIN systems sys ON sys.id=s.system_id JOIN users u ON u.id=s.user_id;
INSERT INTO satisfactions(evaluation_id,answers,average) SELECT id,satisfaction_answers,satisfaction_average FROM mock_eval_seed WHERE json_array_length(satisfaction_answers)>0;
INSERT INTO assessment_answers(evaluation_id,question_id,assessment_type,phase,question_text,answer_value) SELECT e.id,q.id,'effectiveness','before',q.text,CAST(json_extract(e.before_answers,'$['||(q.sort_order-1)||']') AS TEXT) FROM evaluations e JOIN assessment_questions q ON q.system_id=e.system_id AND q.assessment_type='effectiveness' AND q.active=1 WHERE e.id GLOB 'mock-eval-*' AND q.sort_order<=json_array_length(e.before_answers);
INSERT INTO assessment_answers(evaluation_id,question_id,assessment_type,phase,question_text,answer_value) SELECT e.id,q.id,'effectiveness','after',q.text,CAST(json_extract(e.after_answers,'$['||(q.sort_order-1)||']') AS TEXT) FROM evaluations e JOIN assessment_questions q ON q.system_id=e.system_id AND q.assessment_type='effectiveness' AND q.active=1 WHERE e.id GLOB 'mock-eval-*' AND q.sort_order<=json_array_length(e.after_answers);
INSERT INTO assessment_answers(evaluation_id,question_id,assessment_type,phase,question_text,answer_value) SELECT e.id,q.id,'satisfaction','submitted',q.text,CAST(json_extract(s.answers,'$['||(q.sort_order-1)||']') AS TEXT) FROM evaluations e JOIN satisfactions s ON s.evaluation_id=e.id JOIN assessment_questions q ON q.system_id=e.system_id AND q.assessment_type='satisfaction' AND q.active=1 WHERE e.id GLOB 'mock-eval-*' AND q.sort_order<=json_array_length(s.answers);
