คำขอ","direction":"increase","weight":15,"source":"development-mock","active":true,"required":true},{"id":"sat_staff","name":"ความพึงพอใจของผู้ดำเนินการและเจ้าหน้าที่","unit":"1–5","basis":"ต่อคำขอ","direction":"increase","weight":10,"source":"development-mock","active":true,"required":true},{"id":"requester_minutes","name":"เวลาที่ผู้ส่งคำขอใช้ต่อครั้ง","unit":"นาที","basis":"ต่อคำขอ","direction":"decrease","weight":5,"source":"development-mock","active":true,"required":true},{"id":"staff_minutes","name":"เวลาจัดการเอกสารของเจ้าหน้าที่ต่อเรื่อง","unit":"นาที","basis":"ต่อคำขอ","direction":"decrease","weight":7,"source":"development-mock","active":true,"required":true},{"id":"cost_per_case","name":"ต้นทุนรวมต่อเรื่อง","unit":"บาท","basis":"ต่อคำขอ","direction":"decrease","weight":8,"source":"development-mock","active":true,"required":true}]')),'values',json(q.values_json),'submittedAt',q.submitted_at,'kind','quantitative'),q.submitted_at FROM mock_quant_seed q JOIN users u ON u.id=q.user_id;
